	  // Close the suggestion panel on Escape or a click outside it. Emptying the panel
	  // is what hides it (CSS :empty), so this only has to clear it.
	  (function () {
	    var box = document.currentScript.parentNode;
	    var panel = box.querySelector('.kt-search-suggest');
	    function close () { while (panel.firstChild) { panel.removeChild(panel.firstChild); } }
	    document.addEventListener('click', function (e) { if (!box.contains(e.target)) { close(); } });
	    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') { close(); } });
	  })();
